		if ( !found ) {
			return ValidationResults.PROGRAM_FAIL;
		}
		try {
			Integer.parseInt(accessionNumber.substring(INCREMENT_START));
		} catch (NumberFormatException e) {
			return ValidationResults.FORMAT_FAIL;
		}
		return ValidationResults.SUCCESS;
	}
